using AfriWallet.Compliance.Readiness.Models;
namespace AfriWallet.Compliance.Readiness.Checks;
public sealed class SecretBoundaryCheck:IComplianceReadinessCheck { public string Code=>"CMP-RDY-004";public Task<ReadinessCheck> ExecuteAsync(string root,CancellationToken ct=default){string[] patterns=[string.Concat("BEGIN PRIVATE"," KEY"),string.Concat("BEGIN RSA PRIVATE"," KEY"),string.Concat("github","_pat_"),string.Concat("gh","p_")];var hits=new List<string>();foreach(var file in RepositoryCheckUtilities.EnumerateTextFiles(RepositoryCheckUtilities.Resolve(root,"backend","src","Compliance"))){ct.ThrowIfCancellationRequested();var text=File.ReadAllText(file);foreach(var p in patterns)if(text.Contains(p,StringComparison.Ordinal))hits.Add($"{Path.GetFileName(file)}:{p}");}return Task.FromResult(new ReadinessCheck(Code,"Embedded secret boundary",hits.Count==0?ReadinessStatus.Passed:ReadinessStatus.Failed,hits.Count==0?"No embedded secret pattern detected":string.Join(", ",hits)));} }